12	 *
13	 * Celsius is the storage and reasoning unit everywhere: Open-Meteo is requested
14	 * in it, `weatherRules` compares against Celsius thresholds, and the re-rank
15	 * prompt states °C to the model. This function is the ONLY place the user's
16	 * preference is applied, and it sits at the render boundary — converting any
17	 * earlier would put Fahrenheit numbers in front of rules that read them as
18	 * Celsius.
19	 *
20	 * The degree sign is bare in both units, as `Fitcheck.dc.html` draws it. The
21	 * unit is established once on the Settings screen rather than repeated beside
22	 * every number.
23	 */
24	export function formatTemp(tempC: number, unit: TempUnit = "C"): string {
25	  const value = unit === "F" ? toFahrenheit(tempC) : Math.round(tempC);
