94	  // precision never reaches Open-Meteo. timezone=auto makes both `current.time`
95	  // and `hourly.time` local to the coords (otherwise they come back as GMT).
96	  const la = roundCoord(lat);
97	  const lo = roundCoord(lon);
98	  const url =
99	    `https://api.open-meteo.com/v1/forecast?latitude=${la}&longitude=${lo}` +
100	    `&current=temperature_2m,apparent_temperature,weather_code` +
101	    `&hourly=temperature_2m,weather_code,precipitation_probability` +
102	    // `daily` is what the LOOK is built for; `current` is what the screen shows.
103	    `&daily=temperature_2m_max,temperature_2m_min` +
104	    `&forecast_hours=24&forecast_days=1&timezone=auto`;
105	  const res = await fetch(url, { next: { revalidate: 1800 } });
106	  return mapForecast(await res.json(), nowIso);
